 allowed_kinds TEXT NOT NULL CHECK(json_valid(allowed_kinds)),scopes TEXT NOT NULL CHECK(json_valid(scopes)),created_at TEXT NOT NULL,revoked_at TEXT
);
CREATE TABLE devices (
 installation_id TEXT PRIMARY KEY,name TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,allowed_kinds TEXT NOT NULL CHECK(json_valid(allowed_kinds)),
 sim_slot bigint CHECK(sim_slot IN(0,1)),ready bigint NOT NULL DEFAULT 0 CHECK(ready IN(0,1)),revoked_at TEXT,created_at TEXT NOT NULL,last_seen_at TEXT,
 app_version TEXT,os_version TEXT,fcm_token TEXT,fcm_rejected_token_hash TEXT,fcm_pending bigint NOT NULL DEFAULT 0,fcm_next_at TEXT,fcm_attempts bigint NOT NULL DEFAULT 0,fcm_last_error TEXT,
 wake_revision bigint NOT NULL DEFAULT 0,health_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE campaigns (
 campaign_id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(application_id),name TEXT NOT NULL,text TEXT NOT NULL,
 recipients_json TEXT NOT NULL CHECK(json_valid(recipients_json)),recipient_count bigint NOT NULL,expansion_cursor bigint NOT NULL DEFAULT 0,
 request_key TEXT NOT NULL,request_digest TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','running','paused','cancelled','completed')),
 not_after TEXT NOT NULL,scheduled_at TEXT NOT NULL,segments_per_minute bigint NOT NULL CHECK(segments_per_minute BETWEEN 1 AND 6000),segments_per_message bigint NOT NULL,
 created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(application_id,request_key)
);
