 PRIMARY KEY(application_id,phone,purpose)
);
CREATE TABLE otp_challenges (
 challenge_id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(application_id),phone TEXT NOT NULL,purpose TEXT NOT NULL,generation bigint NOT NULL,
 verifier TEXT NOT NULL,expires_at TEXT NOT NULL,remaining_attempts bigint NOT NULL CHECK(remaining_attempts BETWEEN 0 AND 5),consumed_at TEXT,created_at TEXT NOT NULL
);
