CREATE OR REPLACE FUNCTION trigger_otp_issuance_limits() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF (SELECT COUNT(*) FROM otp_challenges WHERE application_id=NEW.application_id AND phone=NEW.phone AND created_at>to_char((NEW.created_at::timestamptz-interval '10 minutes') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))>=6 THEN RAISE EXCEPTION 'otp_phone_rate' USING ERRCODE='23514'; END IF;
 IF (SELECT COUNT(*) FROM otp_challenges WHERE application_id=NEW.application_id AND created_at>to_char((NEW.created_at::timestamptz-interval '1 minutes') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))>=120 THEN RAISE EXCEPTION 'otp_application_rate' USING ERRCODE='23514'; END IF;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER otp_issuance_limits BEFORE INSERT ON otp_challenges FOR EACH ROW EXECUTE FUNCTION trigger_otp_issuance_limits();
ALTER TABLE otp_challenges ENABLE ALWAYS TRIGGER otp_issuance_limits;
CREATE TABLE messages (
 message_id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(application_id),kind TEXT NOT NULL CHECK(kind IN('otp','receipt','operation','campaign')),
 to_number TEXT NOT NULL,text TEXT NOT NULL,payload_digest TEXT NOT NULL,request_digest TEXT NOT NULL,idempotency_key TEXT NOT NULL,
 priority bigint NOT NULL CHECK(priority BETWEEN 0 AND 127),not_after TEXT NOT NULL,available_at TEXT NOT NULL,owner_installation_id TEXT REFERENCES devices(installation_id),assignment_version bigint NOT NULL DEFAULT 0,
 state TEXT NOT NULL DEFAULT 'accepted' CHECK(state IN('accepted','assigned','phone_accepted','queued','handoff_started','sent','delivered','delivery_unconfirmed','partial','expired','cancelled','failed','outcome_unknown')),
 cancel_requested bigint NOT NULL DEFAULT 0 CHECK(cancel_requested IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,phone_accepted_at TEXT,
 campaign_id TEXT REFERENCES campaigns(campaign_id),otp_challenge_id TEXT REFERENCES otp_challenges(challenge_id),metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json)),
 requires_fresh_decision bigint NOT NULL DEFAULT 0 CHECK(requires_fresh_decision IN(0,1)),eligibility_until TEXT,segments_estimate bigint NOT NULL CHECK(segments_estimate>0),
 unknown_observed bigint NOT NULL DEFAULT 0,failure_observed bigint NOT NULL DEFAULT 0,UNIQUE(application_id,idempotency_key),
 CHECK((owner_installation_id IS NULL AND assignment_version=0) OR (owner_installation_id IS NOT NULL AND assignment_version>=1))
);
CREATE INDEX messages_pending ON messages(owner_installation_id,state,priority DESC,available_at);
CREATE INDEX messages_application ON messages(application_id,created_at DESC);
CREATE INDEX messages_campaign ON messages(campaign_id,state);
