 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF NEW.parts_total IS NOT NULL AND (
 EXISTS(SELECT 1 FROM attempts WHERE message_id=NEW.message_id AND attempt_id=NEW.attempt_id AND parts_total IS NOT NULL AND parts_total<>NEW.parts_total)
 OR EXISTS(SELECT 1 FROM message_parts WHERE message_id=NEW.message_id AND attempt_id=NEW.attempt_id AND part_index>=NEW.parts_total)) THEN
RAISE EXCEPTION 'event_part_count_conflict' USING ERRCODE='23514';
