CREATE OR REPLACE FUNCTION trigger_event_suppression() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF NOT EXISTS(SELECT 1 FROM device_events WHERE event_id=NEW.event_id) AND NEW.type IN('cancelled','expired') AND (
 EXISTS(SELECT 1 FROM attempts WHERE message_id=NEW.message_id AND ((handoff_at IS NOT NULL AND aborted_before_call=0 AND NOT(NEW.type='expired' AND COALESCE(NEW.error_code,'')='DEADLINE_BEFORE_CALL' AND NEW.attempt_id=attempt_id)) OR unknown_observed=1))
 OR EXISTS(SELECT 1 FROM messages WHERE message_id=NEW.message_id AND unknown_observed=1) OR EXISTS(SELECT 1 FROM message_parts WHERE message_id=NEW.message_id)) THEN
RAISE EXCEPTION 'handoff_cannot_be_suppressed' USING ERRCODE='23514';
END IF;
RETURN NEW;
END$gateway_trigger$;
