CREATE OR REPLACE FUNCTION trigger_event_abort_evidence() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF NOT EXISTS(SELECT 1 FROM device_events WHERE event_id=NEW.event_id) AND NEW.error_code IN('ABORTED_BEFORE_CALL','DEADLINE_BEFORE_CALL') AND (
 NEW.attempt_id IS NULL OR EXISTS(SELECT 1 FROM message_parts WHERE message_id=NEW.message_id AND attempt_id=NEW.attempt_id)
 OR EXISTS(SELECT 1 FROM attempts WHERE message_id=NEW.message_id AND attempt_id=NEW.attempt_id AND unknown_observed=1)) THEN
RAISE EXCEPTION 'event_abort_conflicts_with_evidence' USING ERRCODE='23514';
END IF;
RETURN NEW;
END$gateway_trigger$;
