CREATE OR REPLACE FUNCTION trigger_permit_charge() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
UPDATE campaign_budget SET used_segments=used_segments+NEW.segments WHERE campaign_id=NEW.campaign_id AND window_start=NEW.window_start;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER permit_charge AFTER INSERT ON dispatch_permits FOR EACH ROW EXECUTE FUNCTION trigger_permit_charge();
ALTER TABLE dispatch_permits ENABLE ALWAYS TRIGGER permit_charge;
