CREATE OR REPLACE FUNCTION trigger_message_wake() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
UPDATE devices SET fcm_pending=1,fcm_next_at=NEW.created_at,wake_revision=wake_revision+1 WHERE revoked_at IS NULL AND ready=1 AND EXISTS(SELECT 1 FROM json_each(devices.allowed_kinds) WHERE value=NEW.kind);
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER message_wake AFTER INSERT ON messages FOR EACH ROW EXECUTE FUNCTION trigger_message_wake();
ALTER TABLE messages ENABLE ALWAYS TRIGGER message_wake;

