-- Retained identities/digests prevent redacted content being re-created on replay.
CREATE OR REPLACE FUNCTION trigger_message_no_rehydration() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF OLD.content_redacted_at IS NOT NULL AND (
 NEW.text<>OLD.text OR NEW.metadata_json<>OLD.metadata_json OR
 NEW.payload_digest<>OLD.payload_digest OR NEW.request_digest<>OLD.request_digest OR
 NEW.content_redacted_at IS NULL OR NEW.message_id<>OLD.message_id OR
 NEW.application_id<>OLD.application_id OR NEW.idempotency_key<>OLD.idempotency_key) THEN
RAISE EXCEPTION 'event_content_redacted' USING ERRCODE='23514';
END IF;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER message_no_rehydration BEFORE UPDATE ON messages FOR EACH ROW EXECUTE FUNCTION trigger_message_no_rehydration();
ALTER TABLE messages ENABLE ALWAYS TRIGGER message_no_rehydration;
CREATE OR REPLACE FUNCTION trigger_campaign_no_rehydration() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF OLD.content_redacted_at IS NOT NULL AND (
 NEW.text<>OLD.text OR NEW.recipients_json<>OLD.recipients_json OR
 NEW.request_digest<>OLD.request_digest OR NEW.request_key<>OLD.request_key OR
 NEW.content_redacted_at IS NULL OR NEW.campaign_id<>OLD.campaign_id OR NEW.application_id<>OLD.application_id OR
 NEW.status IN('draft','running','paused')) THEN
RAISE EXCEPTION 'event_content_redacted' USING ERRCODE='23514';
END IF;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER campaign_no_rehydration BEFORE UPDATE ON campaigns FOR EACH ROW EXECUTE FUNCTION trigger_campaign_no_rehydration();
ALTER TABLE campaigns ENABLE ALWAYS TRIGGER campaign_no_rehydration;
DROP TRIGGER contribution_immutable ON contribution_events;
CREATE OR REPLACE FUNCTION trigger_contribution_immutable() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF NEW.application_id<>OLD.application_id OR NEW.event_id<>OLD.event_id OR
 NEW.facts_digest<>OLD.facts_digest OR NEW.created_at<>OLD.created_at OR
 (OLD.content_redacted_at IS NOT NULL AND (NEW.facts_json<>OLD.facts_json OR NEW.content_redacted_at IS NULL)) OR
 (OLD.content_redacted_at IS NULL AND NEW.facts_json<>OLD.facts_json AND NOT(NEW.facts_json='{}' AND NEW.content_redacted_at IS NOT NULL)) THEN
RAISE EXCEPTION 'event_immutable' USING ERRCODE='23514';
END IF;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER contribution_immutable BEFORE UPDATE ON contribution_events FOR EACH ROW EXECUTE FUNCTION trigger_contribution_immutable();
ALTER TABLE contribution_events ENABLE ALWAYS TRIGGER contribution_immutable;
-- Reduce new late callback details after content redaction, retaining the phase
-- used by event_apply, but never resetting its digest, owner or per-part evidence.
CREATE OR REPLACE FUNCTION trigger_late_event_detail_redaction() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF EXISTS(SELECT 1 FROM messages WHERE message_id=NEW.message_id AND content_redacted_at IS NOT NULL) THEN
UPDATE device_events SET detail_json=CASE WHEN json_extract(detail_json,'$.phase')='delivery' THEN '{"phase":"delivery"}' ELSE '{}' END,
 detail_redacted_at=NEW.received_at WHERE event_id=NEW.event_id;
END IF;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER late_event_detail_redaction AFTER INSERT ON device_events FOR EACH ROW EXECUTE FUNCTION trigger_late_event_detail_redaction();
ALTER TABLE device_events ENABLE ALWAYS TRIGGER late_event_detail_redaction;

