CREATE OR REPLACE FUNCTION trigger_capacity_required() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF NOT EXISTS(SELECT 1 FROM otp_capacity_reservations WHERE message_id=NEW.message_id) THEN
RAISE EXCEPTION 'otp_capacity_unavailable' USING ERRCODE='23514';
END IF;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER capacity_required BEFORE INSERT ON otp_capacity_requirements FOR EACH ROW EXECUTE FUNCTION trigger_capacity_required();
ALTER TABLE otp_capacity_requirements ENABLE ALWAYS TRIGGER capacity_required;
CREATE TABLE sms_templates(
 application_id TEXT NOT NULL REFERENCES applications(application_id),template_key TEXT NOT NULL,version bigint NOT NULL CHECK(version>0),
 locale TEXT NOT NULL CHECK(locale IN('en','rw','fr')),kind TEXT NOT NULL CHECK(kind IN('receipt','operation','campaign','otp')),
 body TEXT NOT NULL,schema_json TEXT NOT NULL CHECK(json_valid(schema_json)),digest TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','published')),
 created_at TEXT NOT NULL,PRIMARY KEY(application_id,template_key,version,locale)
);
CREATE OR REPLACE FUNCTION trigger_template_immutable() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF NEW.body<>OLD.body OR NEW.schema_json<>OLD.schema_json OR NEW.digest<>OLD.digest OR NEW.kind<>OLD.kind
 OR NEW.application_id<>OLD.application_id OR NEW.template_key<>OLD.template_key OR NEW.version<>OLD.version OR NEW.locale<>OLD.locale
 OR (OLD.status='published' AND NEW.status<>'published') THEN
RAISE EXCEPTION 'template_immutable' USING ERRCODE='23514';
END IF;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER template_immutable BEFORE UPDATE ON sms_templates FOR EACH ROW EXECUTE FUNCTION trigger_template_immutable();
ALTER TABLE sms_templates ENABLE ALWAYS TRIGGER template_immutable;
CREATE TABLE notification_schedules(
 schedule_id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(application_id),request_key TEXT NOT NULL,
 request_digest TEXT NOT NULL,name TEXT NOT NULL,to_number TEXT NOT NULL,template_key TEXT NOT NULL,template_version bigint NOT NULL,locale TEXT NOT NULL,
 variables_json TEXT NOT NULL CHECK(json_valid(variables_json)),interval_seconds bigint NOT NULL CHECK(interval_seconds BETWEEN 60 AND 31536000),
 ttl_seconds bigint NOT NULL CHECK(ttl_seconds BETWEEN 30 AND 86400),next_at TEXT NOT NULL,ends_at TEXT NOT NULL,
 active bigint NOT NULL DEFAULT 0 CHECK(active IN(0,1)),revision bigint NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,
 UNIQUE(application_id,request_key)
);
CREATE INDEX schedules_due ON notification_schedules(active,next_at,schedule_id);
CREATE TABLE schedule_occurrences(
 schedule_id TEXT NOT NULL REFERENCES notification_schedules(schedule_id),revision bigint NOT NULL,due_at TEXT NOT NULL,
 message_id TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('queued','expired')),
 PRIMARY KEY(schedule_id,revision,due_at)
);
CREATE TABLE webhook_endpoints(
 endpoint_id TEXT PRIMARY KEY,application_id TEXT UNIQUE REFERENCES applications(application_id),url TEXT NOT NULL,
 secret_cipher TEXT NOT NULL,enabled bigint NOT NULL CHECK(enabled IN(0,1)),generation bigint NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL
);
-- A NULL application identifies the deployment's alert receiver (at most one).
CREATE UNIQUE INDEX one_alert_receiver ON webhook_endpoints((1)) WHERE application_id IS NULL;
CREATE TABLE webhook_deliveries(
 delivery_id TEXT PRIMARY KEY,endpoint_id TEXT NOT NULL REFERENCES webhook_endpoints(endpoint_id),endpoint_generation bigint NOT NULL,
 event_key TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','sending','delivered','failed','cancelled')),
 attempts bigint NOT NULL DEFAULT 0,next_at TEXT NOT NULL,lease_id TEXT,lease_until TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,last_error TEXT,
 UNIQUE(endpoint_id,event_key)
);
CREATE INDEX webhook_due ON webhook_deliveries(state,next_at,lease_until);
CREATE OR REPLACE FUNCTION trigger_callback_message_created() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
INSERT INTO webhook_deliveries(delivery_id,endpoint_id,endpoint_generation,event_key,payload_json,next_at,created_at,updated_at)
 SELECT 'delivery_'||replace(gen_random_uuid()::text,'-',''),e.endpoint_id,e.generation,'created:'||NEW.message_id,
 jsonb_build_object('type','message.state','message_id',NEW.message_id,'application_id',NEW.application_id,'state',NEW.state,'occurred_at',NEW.created_at)::text,
 NEW.created_at,NEW.created_at,NEW.created_at FROM webhook_endpoints e WHERE e.application_id=NEW.application_id AND e.enabled=1;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER callback_message_created AFTER INSERT ON messages FOR EACH ROW EXECUTE FUNCTION trigger_callback_message_created();
ALTER TABLE messages ENABLE ALWAYS TRIGGER callback_message_created;
CREATE OR REPLACE FUNCTION trigger_callback_message_state() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF NEW.state<>OLD.state THEN
INSERT INTO webhook_deliveries(delivery_id,endpoint_id,endpoint_generation,event_key,payload_json,next_at,created_at,updated_at)
 SELECT 'delivery_'||replace(gen_random_uuid()::text,'-',''),e.endpoint_id,e.generation,'state:'||NEW.message_id||':'||replace(gen_random_uuid()::text,'-',''),
 jsonb_build_object('type','message.state','message_id',NEW.message_id,'application_id',NEW.application_id,'state',NEW.state,'occurred_at',NEW.updated_at)::text,
 NEW.updated_at,NEW.updated_at,NEW.updated_at FROM webhook_endpoints e WHERE e.application_id=NEW.application_id AND e.enabled=1;
END IF;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER callback_message_state AFTER UPDATE OF state ON messages FOR EACH ROW EXECUTE FUNCTION trigger_callback_message_state();
ALTER TABLE messages ENABLE ALWAYS TRIGGER callback_message_state;
