CREATE OR REPLACE FUNCTION trigger_callback_alert() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
INSERT INTO webhook_deliveries(delivery_id,endpoint_id,endpoint_generation,event_key,payload_json,next_at,created_at,updated_at)
 SELECT 'delivery_'||replace(gen_random_uuid()::text,'-',''),e.endpoint_id,e.generation,NEW.event_id,
 jsonb_build_object('type','service.alert','alert_key',NEW.alert_key,'transition',NEW.transition,'occurred_at',NEW.at)::text,NEW.at,NEW.at,NEW.at
 FROM webhook_endpoints e WHERE e.application_id IS NULL AND e.enabled=1;
RETURN NEW;
END$gateway_trigger$;
