-- Authoritative ledger snapshots are copied for notification only, never computed here.
CREATE TABLE ledger_notification_events(application_id TEXT NOT NULL REFERENCES applications(application_id),event_id TEXT NOT NULL,facts_json TEXT NOT NULL,facts_digest TEXT NOT NULL,created_at TEXT NOT NULL,redacted_at TEXT,PRIMARY KEY(application_id,event_id));
CREATE TABLE ledger_notification_receipts(application_id TEXT NOT NULL,event_id TEXT NOT NULL,recipient TEXT NOT NULL,message_id TEXT NOT NULL UNIQUE REFERENCES messages(message_id),PRIMARY KEY(application_id,event_id,recipient),FOREIGN KEY(application_id,event_id) REFERENCES ledger_notification_events(application_id,event_id));
CREATE OR REPLACE FUNCTION trigger_ledger_notification_immutable() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF NEW.facts_digest<>OLD.facts_digest OR (NEW.facts_json<>OLD.facts_json AND NOT(OLD.redacted_at IS NULL AND NEW.redacted_at IS NOT NULL AND NEW.facts_json='{}')) OR (OLD.redacted_at IS NOT NULL AND NEW.redacted_at IS DISTINCT FROM OLD.redacted_at) THEN
RAISE EXCEPTION 'ledger_snapshot_immutable' USING ERRCODE='23514';
END IF;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER ledger_notification_immutable BEFORE UPDATE ON ledger_notification_events FOR EACH ROW EXECUTE FUNCTION trigger_ledger_notification_immutable();
ALTER TABLE ledger_notification_events ENABLE ALWAYS TRIGGER ledger_notification_immutable;

-- Source: 0004_final_hardening.sql
-- Additive final-source hardening. Does not erase or replay existing jobs.
CREATE OR REPLACE FUNCTION trigger_ledger_no_recipient_after_redaction() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF EXISTS(SELECT 1 FROM ledger_notification_events e WHERE e.application_id=NEW.application_id
 AND e.event_id=NEW.event_id AND e.redacted_at IS NOT NULL)
 AND NOT EXISTS(SELECT 1 FROM ledger_notification_receipts r WHERE r.application_id=NEW.application_id
 AND r.event_id=NEW.event_id AND r.recipient=NEW.recipient) THEN
RAISE EXCEPTION 'source_facts_redacted' USING ERRCODE='23514';
END IF;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER ledger_no_recipient_after_redaction BEFORE INSERT ON ledger_notification_receipts FOR EACH ROW EXECUTE FUNCTION trigger_ledger_no_recipient_after_redaction();
ALTER TABLE ledger_notification_receipts ENABLE ALWAYS TRIGGER ledger_no_recipient_after_redaction;
CREATE OR REPLACE FUNCTION trigger_ledger_identity_immutable() RETURNS trigger LANGUAGE plpgsql
 SET search_path=collect_sms,pg_catalog AS $gateway_trigger$
BEGIN
IF NEW.application_id<>OLD.application_id OR NEW.event_id<>OLD.event_id OR NEW.created_at<>OLD.created_at THEN
RAISE EXCEPTION 'ledger_snapshot_immutable' USING ERRCODE='23514';
END IF;
RETURN NEW;
END$gateway_trigger$;
CREATE TRIGGER ledger_identity_immutable BEFORE UPDATE ON ledger_notification_events FOR EACH ROW EXECUTE FUNCTION trigger_ledger_identity_immutable();
ALTER TABLE ledger_notification_events ENABLE ALWAYS TRIGGER ledger_identity_immutable;
