CREATE TABLE application_outbox_health(
 application_id TEXT PRIMARY KEY REFERENCES applications(application_id),
 sampled_at TEXT NOT NULL,received_at TEXT NOT NULL,
 pending_count bigint NOT NULL CHECK(pending_count BETWEEN 0 AND 1000000000),
 failed_count bigint NOT NULL CHECK(failed_count BETWEEN 0 AND 1000000000),
 oldest_pending_at TEXT,
 CHECK((pending_count=0 AND oldest_pending_at IS NULL) OR (pending_count>0 AND oldest_pending_at IS NOT NULL))
);

-- Every mutation, including a direct internal SQL caller, uses the same lock.
-- Adapter batches acquire this before their first read, preserving D1's serial
-- writer ordering for OTP limits, device assignment and segment budgets.
CREATE FUNCTION serialize_gateway_write() RETURNS trigger LANGUAGE plpgsql
 SET search_path=pg_catalog AS $$BEGIN PERFORM pg_advisory_xact_lock(721340019927::bigint); RETURN NULL; END$$;
